-- 🖼 Event graphics: a picture on an event's card (owner 11/19 "put barn
-- night graphic from insta for the cal event so players know its barn night").
--
-- fh_event_graphics links an event (fh_events) to an image in club_files;
-- the calendar feed hands them out as ev.graphics and EventScreen draws
-- them atop the card.  The image must be visibility 'public' so a plain
-- <img> loads it from /api/files/dl/<id>/<name>.  More = another row.
--
-- First one: the Friday Night @ The Barn flyer for Fri Nov 20 (fh_event
-- 75824080), from the club's Instagram post of Nov 16.

CREATE TABLE IF NOT EXISTS fh_event_graphics (
    id            serial PRIMARY KEY,
    fh_event_id   bigint  NOT NULL REFERENCES fh_events(id) ON DELETE CASCADE,
    club_file_id  integer NOT NULL REFERENCES club_files(id) ON DELETE CASCADE,
    source_url    text,
    sort_order    integer NOT NULL DEFAULT 0,
    created_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (fh_event_id, club_file_id)
);
CREATE INDEX IF NOT EXISTS fh_event_graphics_event_idx ON fh_event_graphics (fh_event_id);

COMMENT ON TABLE fh_event_graphics IS 'Pictures shown atop an event card (mig 1584). club_files row must be public.';

-- The tap-to-enlarge hint under a graphic.
INSERT INTO message_templates (category, label, kind, tier, body, is_active, client_side)
SELECT 'Event Center', 'Event graphic caption', 'event_center', 'graphic_open', 'Tap to open full size', true, true
 WHERE NOT EXISTS (SELECT 1 FROM message_templates WHERE kind = 'event_center' AND tier = 'graphic_open');

DO $$
DECLARE fid integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM fh_events WHERE id = 75824080) THEN
    RAISE NOTICE 'fh_event 75824080 missing — barn night graphic skipped';
    RETURN;
  END IF;
  INSERT INTO club_files (title, note, original_filename, mime, byte_size, bytes, visibility)
  VALUES ('Friday Night @ The Barn — Fri Nov 20, 2026',
          'From https://www.instagram.com/p/Df0mEhtjd0w/ (club Instagram, Nov 16). On the Barn Night event card.',
          'barn-night-2026-11-20.jpg', 'image/jpeg', 265899,
          decode('', 'base64'), 'public')
  RETURNING id INTO fid;
  INSERT INTO fh_event_graphics (fh_event_id, club_file_id, source_url)
  VALUES (75824080, fid, 'https://www.instagram.com/p/Df0mEhtjd0w/')
  ON CONFLICT DO NOTHING;
END $$;
